+/* eslint-disable @typescript-eslint/no-explicit-any -- this harness mutates raw, untyped GitHub JSON on purpose */
+import { describe, expect, it } from "vitest";
+import { readFileSync } from "node:fs";
+import path from "node:path";
+
+// prettier-ignore
+// @ts-expect-error - .mjs utility ships without type declarations
+import { PR_KEY_QUERY, keysEqual, parsePrKey } from "../../../scripts/eng/v2/contract/pr-key.mjs";
+import {
+  ENVELOPE_CASES,
+  keyViolation,
+  mulberry32,
+  randomMutation,
+  singlePointCases,
+  type MutationCase,
+} from "./support/key-mutations";
+
+// ===========================================================================
+// ENG-LOOP V1 05A, gap row 1: coherent PR identity, including the draft flag.
+//
